// 1. GET /slot/detail/:id - Slot detail (CAPTURED ✅)
app.get('/slot/detail/:id', (req, res) => {
  const { id } = req.params;

  try {
    const slot = db.prepare(`
      SELECT * FROM slots WHERE id = ?
    `).get(id);

    if (!slot) {
      return res.json({
        result: 'error',
        message: '슬롯을 찾을 수 없습니다.'
      });
    }

    res.json({
      result: 'success',
      data: {
        ID: slot.id.toString(),
        USER_ID: slot.user_id,
        USER_NAME: slot.user_name,
        AGENCY: slot.agency,
        KEYWORD: slot.keyword,
        RANKKEYWORD: slot.rankkeyword,
        RANKING: slot.ranking.toString(),
        RANKING_STATUS: slot.ranking_status,
        STARTDATE: slot.start_date,
        ENDDATE: slot.end_date,
        MEMO: slot.memo || ''
      }
    });
  } catch (error) {
    console.error('Error fetching slot detail:', error);
    res.json({
      result: 'error',
      message: '서버 오류가 발생했습니다.'
    });
  }
});

// 2. GET /slot/detail-hourly/:id - Hourly rankings (CAPTURED ✅)
app.get('/slot/detail-hourly/:id', (req, res) => {
  const { id } = req.params;

  try {
    const slot = db.prepare('SELECT rankkeyword FROM slots WHERE id = ?').get(id);

    if (!slot) {
      return res.json({
        result: 'error',
        message: '슬롯을 찾을 수 없습니다.'
      });
    }

    const hourlyRankings = db.prepare(`
      SELECT time_txt, ranking, ranking_txt
      FROM hourly_rankings
      WHERE slot_id = ?
      ORDER BY id DESC
    `).all(id);

    res.json({
      result: 'success',
      data: {
        keyword: slot.rankkeyword,
        items: hourlyRankings
      }
    });
  } catch (error) {
    console.error('Error fetching hourly rankings:', error);
    res.json({
      result: 'error',
      message: '서버 오류가 발생했습니다.'
    });
  }
});

// 3. POST /slot/memo - Save memo (CAPTURED ✅)
app.post('/slot/memo', (req, res) => {
  const { id, memo } = req.body;

  if (!id) {
    return res.json({
      result: 'error',
      message: 'ID가 필요합니다.'
    });
  }

  try {
    db.prepare(`
      UPDATE slots SET memo = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?
    `).run(memo || '', id);

    res.json({
      result: 'success',
      message: '메모가 수정되었습니다.'
    });
  } catch (error) {
    console.error('Error saving memo:', error);
    res.json({
      result: 'error',
      message: '서버 오류가 발생했습니다.'
    });
  }
});

// 4. POST /slot/set-inline - Inline edit
app.post('/slot/set-inline', (req, res) => {
  const { slot_id, slot_keyword, slot_rankkeyword, slot_memo } = req.body;

  if (!slot_id) {
    return res.json({
      result: 'error',
      message: 'ID가 필요합니다.'
    });
  }

  try {
    db.prepare(`
      UPDATE slots
      SET keyword = COALESCE(?, keyword),
          rankkeyword = COALESCE(?, rankkeyword),
          memo = COALESCE(?, memo),
          updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `).run(slot_keyword, slot_rankkeyword, slot_memo, slot_id);

    res.json({
      result: 'success',
      message: '수정이 저장되었습니다.'
    });
  } catch (error) {
    console.error('Error updating slot inline:', error);
    res.json({
      result: 'error',
      message: '서버 오류가 발생했습니다.'
    });
  }
});

