// 6. POST /slot/set-all - Bulk update
app.post('/slot/set-all', (req, res) => {
  const { id, slot_userid, slot_agency, slot_keyword, slot_rankkeyword, slot_startdate, slot_enddate } = req.body;

  const ids = Array.isArray(id) ? id : [id];

  if (!ids.length) {
    return res.json({
      result: 'error',
      message: '선택된 슬롯이 없습니다.'
    });
  }

  try {
    const update = db.prepare(`
      UPDATE slots
      SET user_id = COALESCE(?, user_id),
          agency = COALESCE(?, agency),
          keyword = COALESCE(?, keyword),
          rankkeyword = COALESCE(?, rankkeyword),
          start_date = COALESCE(?, start_date),
          end_date = COALESCE(?, end_date),
          updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `);

    for (const slotId of ids) {
      update.run(slot_userid, slot_agency, slot_keyword, slot_rankkeyword, slot_startdate, slot_enddate, slotId);
    }

    res.json({
      result: 'success',
      message: `${ids.length}개 슬롯이 수정되었습니다.`
    });
  } catch (error) {
    console.error('Error bulk updating slots:', error);
    res.json({
      result: 'error',
      message: '서버 오류가 발생했습니다.'
    });
  }
});

// 7. POST /slot/delete - Delete slots
app.post('/slot/delete', (req, res) => {
  const ids = req.body.id || [];

  if (!ids.length) {
    return res.json({
      result: 'error',
      message: '선택된 슬롯이 없습니다.'
    });
  }

  try {
    const deleteStmt = db.prepare('DELETE FROM slots WHERE id = ?');

    for (const id of ids) {
      deleteStmt.run(id);
    }

    res.json({
      result: 'success',
      message: `${ids.length}개 슬롯이 삭제되었습니다.`
    });
  } catch (error) {
    console.error('Error deleting slots:', error);
    res.json({
      result: 'error',
      message: '서버 오류가 발생했습니다.'
    });
  }
});

// 8. POST /slot/init-slot - Reset slots
app.post('/slot/init-slot', (req, res) => {
  const ids = req.body.id || [];

  if (!ids.length) {
    return res.json({
      result: 'error',
      message: '선택된 슬롯이 없습니다.'
    });
  }

  try {
    const reset = db.prepare(`
      UPDATE slots
      SET ranking = 999,
          ranking_status = 'X',
          memo = '',
          updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `);

    for (const id of ids) {
      reset.run(id);
    }

    res.json({
      result: 'success',
      message: `${ids.length}개 슬롯이 초기화되었습니다.`
    });
  } catch (error) {
    console.error('Error resetting slots:', error);
    res.json({
      result: 'error',
      message: '서버 오류가 발생했습니다.'
    });
  }
});

// 9. POST /slot/remain-deduct - Deduct remaining days
app.post('/slot/remain-deduct', (req, res) => {
  const { id, days } = req.body;
  const ids = Array.isArray(id) ? id : [id];
  const deductDays = parseInt(days) || 0;

  if (!ids.length || deductDays <= 0) {
    return res.json({
      result: 'error',
      message: '잘못된 요청입니다.'
    });
  }

  try {
    const deduct = db.prepare(`
      UPDATE slots
      SET end_date = date(end_date, '-' || ? || ' days'),
          updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
    `);

    for (const slotId of ids) {
      deduct.run(deductDays, slotId);
    }

    res.json({
      result: 'success',
      message: `${deductDays}일이 차감되었습니다.`
    });
  } catch (error) {
    console.error('Error deducting days:', error);
    res.json({
      result: 'error',
      message: '서버 오류가 발생했습니다.'
    });
  }
});

