// 13. GET /member/search - User search
app.get('/member/search', (req, res) => {
  const { q } = req.query;
  const query = (q || '').toLowerCase();

  try {
    const users = db.prepare(`
      SELECT user_id as USER_ID, user_name as USER_NAME
      FROM users
      WHERE LOWER(user_id) LIKE ? OR LOWER(user_name) LIKE ?
    `).all(`%${query}%`, `%${query}%`);

    res.json(users);
  } catch (error) {
    console.error('Error searching users:', error);
    res.json([]);
  }
});

