// 15. POST /slot/add - Create new slots
app.post('/slot/add', (req, res) => {
  const {
    slot_userid,
    slot_count,
    slot_limit,
    slot_type,
    slot_end_date,
    slot_today
  } = req.body;

  try {
    // Get user info
    const user = db.prepare(`
      SELECT user_name FROM users WHERE user_id = ?
    `).get(slot_userid);

    if (!user) {
      return res.json({
        result: 'error',
        message: '사용자를 찾을 수 없습니다.'
      });
    }

    // Calculate dates
    const startDate = slot_today == 1 ? new Date() : new Date();
    const endDate = slot_end_date ? new Date(slot_end_date.replace(/\./g, '-')) : new Date();
    endDate.setDate(endDate.getDate() + parseInt(slot_limit || 30));

    const formatDate = (date) => {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return `${year}.${month}.${day}`;
    };

    // Insert slots
    const insert = db.prepare(`
      INSERT INTO slots (
        user_id, user_name, agency, keyword, rankkeyword,
        ranking, ranking_status, slot_type,
        start_date, end_date, memo
      ) VALUES (?, ?, '', '', '', 999, 'X', ?, ?, ?, '')
    `);

    const count = parseInt(slot_count || 1);
    for (let i = 0; i < count; i++) {
      insert.run(
        slot_userid,
        user.user_name,
        slot_type || 'NA',
        formatDate(startDate),
        formatDate(endDate)
      );
    }

    res.json({
      result: 'success',
      message: `${count}개의 슬롯이 생성되었습니다.`
    });
  } catch (error) {
    console.error('Error creating slots:', error);
    res.json({
      result: 'error',
      message: '슬롯 생성에 실패했습니다.'
    });
  }
});

